document.addEventListener("DOMContentLoaded",function(){const timeFilterContainer=document.getElementById("time-filter-container");if(!timeFilterContainer)return;const severityColors={critical:"#d64545",warning:"#e5a13b",caution:"#e5cf0d",normal:"#97b552"};const severityLabels={critical:gettext("Critical"),warning:gettext("Warning"),caution:gettext("Caution"),normal:gettext("Normal")};const trendLabels={up:gettext("Increasing"),down:gettext("Decreasing"),neutral:gettext("Neutral")};const severityOrder=["critical","warning","caution","normal"];let ndx=crossfilter([]);const dateDimension=ndx.dimension(d=>d.date);const moduleDimension=ndx.dimension(d=>d.module);const severityDimension=ndx.dimension(d=>d.severity);const trendDimension=ndx.dimension(d=>d.trend);const countryDimension=ndx.dimension(d=>d.country_slug);const riskCodeDimension=ndx.dimension(d=>d.risk_code);const volumeByDayGroup=dateDimension.group(d3.timeDay).reduceSum(d=>d.issue_count);const moduleGroup=moduleDimension.group().reduceSum(d=>d.issue_count);const severityGroup=severityDimension.group().reduceSum(d=>d.issue_count);const trendGroup=trendDimension.group().reduceSum(d=>d.issue_count);const countryGroup=countryDimension.group().reduceSum(d=>d.issue_count);const riskCodeGroup=riskCodeDimension.group().reduce((p,v)=>{p.issue_count+=v.issue_count;p.risk_name=v.risk_name||p.risk_name;p.module=v.module||p.module;p.severity=v.severity||p.severity;p.trend=v.trend||p.trend;p.percentage=v.percentage;return p},(p,v)=>{p.issue_count-=v.issue_count;return p},()=>({issue_count:0,risk_name:"",module:"",severity:"",trend:"",percentage:null}));const totalIssues=ndx.groupAll().reduceSum(d=>d.issue_count);const criticalIssues=ndx.groupAll().reduceSum(d=>d.severity==="critical"?d.issue_count:0);const warningIssues=ndx.groupAll().reduceSum(d=>d.severity==="warning"?d.issue_count:0);const timelineChart=echarts.init(document.getElementById("time-focus-chart"),"macarons");const moduleChart=echarts.init(document.getElementById("risk-module-chart"),"macarons");const severityChart=echarts.init(document.getElementById("risk-severity-chart"),"macarons");const trendChart=echarts.init(document.getElementById("risk-trend-chart"),"macarons");const countryChart=echarts.init(document.getElementById("risk-country-chart"),"macarons");window.addEventListener("resize",function(){timelineChart.resize();moduleChart.resize();severityChart.resize();trendChart.resize();countryChart.resize()});function formatCount(val){return d3.format(",")(val)}function countDistinct(group){return group.all().filter(d=>d.value>0).length}function updateKPIs(){document.getElementById("total-issues").textContent=formatCount(totalIssues.value());document.getElementById("total-critical").textContent=formatCount(criticalIssues.value());document.getElementById("total-warnings").textContent=formatCount(warningIssues.value());document.getElementById("total-modules").textContent=formatCount(countDistinct(moduleGroup));document.getElementById("total-countries").textContent=formatCount(countDistinct(countryGroup))}function renderSeverityBadge(sev){const badges={critical:'<span class="inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-bold bg-red-600 text-white shadow-xs">Critical</span>',warning:'<span class="inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-bold bg-amber-500 text-white shadow-xs">Warning</span>',caution:'<span class="inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-bold bg-yellow-400 text-yellow-950 shadow-xs">Caution</span>',normal:'<span class="inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-bold bg-emerald-600 text-white shadow-xs">Normal</span>'};return badges[sev]||`<span class="inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-bold bg-gray-200 text-gray-800">${sev}</span>`}function renderTrendBadge(trend){if(trend==="up"){return'<span class="inline-flex items-center gap-1 text-xs font-semibold text-red-600"><svg class="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2.5" d="M13 7h8m0 0v8m0-8l-8 8-4-4-6 6"></path></svg> Increasing</span>'}if(trend==="down"){return'<span class="inline-flex items-center gap-1 text-xs font-semibold text-emerald-600"><svg class="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2.5" d="M13 17h8m0 0V9m0 8l-8-8-4 4-6-6"></path></svg> Decreasing</span>'}return'<span class="inline-flex items-center gap-1 text-xs font-medium text-gray-500"><svg class="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M17 8l4 4m0 0l-4 4m4-4H3"></path></svg> Neutral</span>'}function updateAll(){updateKPIs();const timelineData=volumeByDayGroup.all().filter(d=>d.key!==null).map(d=>[d.key.getTime(),d.value]);timelineChart.setOption({tooltip:{trigger:"axis",formatter:function(params){const date=new Date(params[0].value[0]);return`${d3.timeFormat("%B %d, %Y")(date)}<br/><b>${formatCount(params[0].value[1])}</b> ${gettext("issues")}`}},grid:{top:20,bottom:60,left:60,right:20},xAxis:{type:"time",axisLabel:{color:"#64748b"}},yAxis:{type:"value",axisLabel:{color:"#64748b"},splitLine:{lineStyle:{type:"dashed",color:"#f1f5f9"}}},series:[{name:gettext("Issues"),type:"bar",data:timelineData,itemStyle:{color:"#5ab1ef"},barMaxWidth:20}]},{notMerge:true});const moduleData=moduleGroup.all().filter(d=>d.key&&d.value>0).sort((a,b)=>b.value-a.value);moduleChart.setOption({tooltip:{trigger:"axis",axisPointer:{type:"shadow"},formatter:params=>`${params[0].name}: <b>${formatCount(params[0].value)}</b>`},grid:{top:20,bottom:30,left:140,right:30},xAxis:{type:"value",axisLabel:{color:"#64748b"},splitLine:{lineStyle:{color:"#f1f5f9"}}},yAxis:{type:"category",data:moduleData.map(d=>d.key),inverse:true,axisLabel:{color:"#1f2937",fontWeight:500,formatter:val=>val.length>22?val.substring(0,22)+"...":val}},series:[{type:"bar",data:moduleData.map(d=>d.value),barMaxWidth:22,itemStyle:{color:"#5ab1ef",borderRadius:[0,4,4,0]}}]},{notMerge:true});const severityData=severityOrder.map(sev=>{const row=severityGroup.all().find(d=>d.key===sev);return{name:severityLabels[sev],value:row?row.value:0,severity:sev}}).filter(d=>d.value>0);severityChart.setOption({tooltip:{trigger:"item",formatter:"{b}: <b>{c}</b> ({d}%)"},series:[{type:"pie",radius:["45%","70%"],center:["50%","50%"],avoidLabelOverlap:true,itemStyle:{borderRadius:6,borderColor:"#fff",borderWidth:2},label:{show:true,position:"outside",formatter:"{b}\n({d}%)",fontSize:11,color:"#374151"},labelLine:{show:true,length:15,length2:10,smooth:false},emphasis:{label:{show:true,fontSize:13,fontWeight:"bold"}},data:severityData.map(d=>({name:d.name,value:d.value,itemStyle:{color:severityColors[d.severity]}}))}]},{notMerge:true});const trendData=trendGroup.all().filter(d=>d.key&&d.value>0);trendChart.setOption({tooltip:{trigger:"item",formatter:"{b}: <b>{c}</b> ({d}%)"},series:[{type:"pie",radius:["45%","70%"],center:["50%","50%"],avoidLabelOverlap:true,itemStyle:{borderRadius:6,borderColor:"#fff",borderWidth:2},label:{show:true,position:"outside",formatter:"{b}\n({d}%)",fontSize:11,color:"#374151"},labelLine:{show:true,length:15,length2:10,smooth:false},emphasis:{label:{show:true,fontSize:13,fontWeight:"bold"}},data:trendData.map(d=>({name:trendLabels[d.key]||d.key,value:d.value}))}]},{notMerge:true});const countryData=countryGroup.all().filter(d=>d.key&&d.value>0).sort((a,b)=>b.value-a.value).slice(0,15);countryChart.setOption({tooltip:{trigger:"axis",axisPointer:{type:"shadow"},formatter:params=>`${params[0].name}: <b>${formatCount(params[0].value)}</b>`},grid:{top:20,bottom:30,left:140,right:30},xAxis:{type:"value",axisLabel:{color:"#64748b"},splitLine:{lineStyle:{color:"#f1f5f9"}}},yAxis:{type:"category",data:countryData.map(d=>d.key),inverse:true,axisLabel:{color:"#1f2937",fontWeight:500,formatter:val=>val.length>22?val.substring(0,22)+"...":val}},series:[{type:"bar",data:countryData.map(d=>d.value),barMaxWidth:22,itemStyle:{color:"#5ab1ef",borderRadius:[0,4,4,0]}}]},{notMerge:true});const topRisks=riskCodeGroup.all().filter(d=>d.key&&d.value.issue_count>0).sort((a,b)=>b.value.issue_count-a.value.issue_count).slice(0,10);const tableBody=document.getElementById("risk-top-table");if(tableBody){tableBody.innerHTML=topRisks.map(d=>{const v=d.value;const pct=v.percentage!==null&&v.percentage!==undefined?`${v.percentage}%`:"—";return`<tr class="hover:bg-slate-50/80 transition-colors">
                    <td class="py-3 px-4 font-semibold text-gray-900 text-sm">${v.risk_name||d.key}</td>
                    <td class="py-3 px-4 text-gray-600 text-xs font-medium">${v.module}</td>
                    <td class="py-3 px-4 text-center">${renderSeverityBadge(v.severity)}</td>
                    <td class="py-3 px-4 text-center">${renderTrendBadge(v.trend)}</td>
                    <td class="py-3 px-4 text-right font-bold text-gray-900 text-sm tabular-nums">${formatCount(v.issue_count)}</td>
                    <td class="py-3 px-4 text-right font-semibold text-gray-700 text-sm tabular-nums">${pct}</td>
                </tr>`}).join("")}}async function loadRange(startDate,endDate){try{const from=timeFilter.formatDateStr(startDate);const to=timeFilter.formatDateStr(endDate);const url=`${window.DASHBOARD_CONFIG.endpoint}?date_from=${from}&date_to=${to}&dashboard=risk`;const response=await fetch(url,{credentials:"same-origin",headers:{Accept:"application/json","X-Requested-With":"XMLHttpRequest"}});if(!response.ok){if(response.status===403){console.error("Authentication required. Please log in.");return}throw new Error(`HTTP error! status: ${response.status}`)}const data=await response.json();const dateFormat=d3.timeParse("%Y-%m-%d");data.forEach(d=>{d.date=dateFormat(d.date);d.issue_count=+d.issue_count;d.percentage=d.percentage===null||d.percentage===undefined?null:+d.percentage;d.severity=d.severity||"normal";d.trend=d.trend||"neutral";d.module=d.module||"";d.risk_code=d.risk_code||d.dimension_value||""});dateDimension.filterAll();ndx.remove();ndx.add(data);timeFilter.setBuffer(startDate,endDate);updateExportLinks(startDate,endDate);updateAll()}catch(error){console.error("Error loading risk data:",error)}}function updateExportLinks(startDate,endDate){const base=window.DASHBOARD_CONFIG.exportEndpoint;const from=timeFilter.formatDateStr(startDate);const to=timeFilter.formatDateStr(endDate);const params=`date_from=${from}&date_to=${to}`;const csv=document.getElementById("export-csv");const xlsx=document.getElementById("export-xlsx");const json=document.getElementById("export-json");if(csv)csv.href=`${base}?format=csv&${params}`;if(xlsx)xlsx.href=`${base}?format=xlsx&${params}`;if(json)json.href=`${base}?format=json&${params}`}const timeFilter=new DashboardTimeFilter({onFilterChange:(startDate,endDate)=>{if(timeFilter.isWithinBuffer(startDate,endDate)){dateDimension.filterRange([startDate,endDate]);updateExportLinks(startDate,endDate);updateAll()}else{loadRange(startDate,endDate)}}});const exportModal=document.getElementById("export-modal");document.getElementById("btn-open-export").addEventListener("click",function(){exportModal.classList.remove("hidden");exportModal.classList.add("flex")});document.getElementById("btn-close-export").addEventListener("click",function(){exportModal.classList.add("hidden");exportModal.classList.remove("flex")});loadRange(timeFilter.currentRange.start,timeFilter.currentRange.end)});
